#include "stm32f7xx.h"

void SystemClock_Config(void);
void USART1_Init(void);
void USART1_SendChar(char c);

int main(void) {
  HAL_Init();
  SystemClock_Config();
  USART1_Init();

  while (1) {
    USART1_SendChar('H');
    USART1_SendChar('e');
    USART1_SendChar('l');
    USART1_SendChar('l');
    USART1_SendChar('o');
    USART1_SendChar(' ');
    USART1_SendChar('S');
    USART1_SendChar('T');
    USART1_SendChar('M');
    USART1_SendChar('3');
    USART1_SendChar('2');
    USART1_SendChar('!');
    USART1_SendChar('\r');
    USART1_SendChar('\n');
    HAL_Delay(1000);
  }
}

void USART1_Init(void) {
  RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;
  RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

  GPIOA->MODER &= ~(3 << (9 * 2));
  GPIOA->MODER |= (2 << (9 * 2));
  GPIOA->AFRL |= (7 << (9 * 4));

  USART1->BRR = 0x683;
  USART1->CR1 = USART_CR1_UE | USART_CR1_TE | USART_CR1_RE;
}

void USART1_SendChar(char c) {
  while (!(USART1->SR & USART_SR_TXE));
  USART1->DR = c;
}

